199:                }
200:                if (listeners != null) {
201:                    switch (event.getEventType()) {
202:                        case CarPropertyEvent.PROPERTY_EVENT_PROPERTY_CHANGE:
203:                            listeners.onPropertyChanged(event);
204:                            break;
205:                        case CarPropertyEvent.PROPERTY_EVENT_ERROR:
206:                            listeners.onErrorEvent(event);
207:                            break;
208:                        default:
209:                            throw new IllegalArgumentException();
210:                    }
211:                }
212:            }
213:        };
