105:            }
106:            SharedMemory memory = SharedMemory.CREATOR.createFromParcel(in);
107:            deserializeSharedMemoryAndClose(memory);
108:        }
109:        in.setDataPosition(startPosition + totalPayloadSize);
110:        if (DBG_PAYLOAD) {
111:            Log.d(TAG, "Read, start:" + startPosition + " totalPayloadSize:" + totalPayloadSize
