136:        // dataParcel is the parcel that would be serialized to the shared memory file.
137:        Parcel dataParcel = Parcel.obtain();
138:        totalPayloadSize = serializeMemoryFdOrPayloadToParcel(dataParcel, flags, null);
139:
140:        boolean noSharedMemory = totalPayloadSize <= MAX_DIRECT_PAYLOAD_SIZE;
141:        boolean hasNonNullPayload = true;
142:        if (noSharedMemory) {
