156:            totalPayloadSize = serializeMemoryFdOrPayloadToParcel(dest, flags, sharedMemory);
157:        }
158:        if (DBG_PAYLOAD) {
159:            Log.d(TAG, "Write, start:" + startPosition + " totalPayloadSize:" + totalPayloadSize
160:                    + " hasNonNullPayload:" + hasNonNullPayload
161:                    + " hasSharedMemory:" + !noSharedMemory + " dataSize:" + dest.dataSize());
162:        }
