230:                for (int i = 0; i < dumpSize; i++) {
231:                    bd.append(data[i]);
232:                    if (i != dumpSize - 1) {
233:                        bd.append(',');
234:                    }
235:                }
236:                bd.append("=memory:");
237:                for (int i = 0; i < dumpSize; i++) {
238:                    bd.append(buffer.get(i));
239:                    if (i != dumpSize - 1) {
