120:        verify(mMockHandler1, timeout(5000)).onEvent(any());
121:
122:        verify(mHalService).subscribeProperty(SPEED_ID, 10f);
123:        verify(mHalService).getPropertySafe(SPEED_ID, 0);
124:
125:        // Clean up invocation state.
126:        clearInvocations(mHalService);
127:        when(mHalService.getSampleRate(SPEED_ID)).thenReturn(10f);
128:
129:        // Register the second listener.
130:        mService.registerListener(SPEED_ID, /* rate= */ 20, mMockHandler2);
